<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/portal.php';
$user=requireStaff();if($user['role']==='admin'){header('Location: admin.php');exit;}
try{
    $status=textInput($_GET,'status');$list=$service->projects((int)$user['id'],textInput($_GET,'q'),$status,integerInput($_GET,'page',1));
    $selected=integerInput($_GET,'project',(int)($list['rows'][0]['id']??0));$project=$selected?$service->project((int)$user['id'],$selected,true):null;
    $feedback=$project?$service->feedback((int)$user['id'],$selected):[];$stats=$service->stats((int)$user['id']);$published=integerInput($_GET,'published')===1;
}catch(AccessDenied $e){http_response_code(403);exit('Project unavailable or not assigned to you.');}catch(InvalidArgumentException $e){http_response_code(400);exit('Invalid filter.');}
portalHeader('Sub-admin dashboard',$user);
?>
<div class="page-heading"><div><p class="eyebrow">REVIEW WORKSPACE / <?= esc(mb_strtoupper($user['name'])) ?></p><h1>Your assigned projects.</h1><p>Review uploaded plans and give clear, actionable architectural feedback.</p></div><a class="button" href="subadmin.php?published=1"><?= icon('imgMessageSquare','subadmin') ?>My published reviews</a></div>
<div class="scope-notice"><?= icon('imgShieldCheck','subadmin') ?><div><strong>Sub admin · Assigned-project access</strong><p>You can review only projects assigned to you and send human feedback. User management, role changes and global project access are reserved for an Admin.</p></div><span class="eyebrow"><?= (int)$stats['total'] ?> ASSIGNED / <?= (int)$stats['drafts'] ?> DRAFT</span></div>
<?php if($published): ?><section class="panel"><h2>My published reviews</h2><p class="hint">Latest 100 published reviews on projects still assigned to you.</p><?php $q=$db->prepare("SELECT f.*,p.name FROM feedback f JOIN projects p ON p.id=f.project_id WHERE f.author_id=? AND p.assigned_to=? AND f.status='published' ORDER BY f.published_at DESC LIMIT 100");$q->execute([$user['id'],$user['id']]);$reviews=$q->fetchAll(PDO::FETCH_ASSOC);if(!$reviews)emptyState('No published reviews','Save a draft or publish feedback from an assigned project.');foreach($reviews as $f): ?><article class="feedback-item"><a href="subadmin.php?project=<?= (int)$f['project_id'] ?>#composer"><strong><?= esc($f['name']) ?></strong></a><p class="hint"><?= esc($f['location']) ?> · <?= dateLabel($f['published_at']) ?></p><p class="preserve"><?= esc($f['body']) ?></p></article><?php endforeach; ?></section><?php endif; ?>
<div class="subadmin-grid"><aside class="stack"><section class="panel"><h2>Review queue · <?= (int)$list['total'] ?> projects</h2><form method="get" class="stack"><label>Status<select name="status"><option value="">All assigned projects</option><?php foreach(['needs_feedback','in_review','awaiting_owner','completed'] as $v): ?><option value="<?= $v ?>" <?= $v===$status?'selected':'' ?>><?= esc(ucwords(str_replace('_',' ',$v))) ?></option><?php endforeach; ?></select></label><button>Filter queue</button></form><div class="review-queue"><?php foreach($list['rows'] as $p): ?><a class="queue-card <?= $selected===(int)$p['id']?'selected':'' ?>" href="?project=<?= (int)$p['id'] ?>"><?= badge($p['status']) ?><h3><?= esc($p['name']) ?></h3><p><?= esc($p['owner_name'].' · '.$p['kind']) ?><br>Received <?= dateLabel($p['created_at']) ?></p><small><?= $selected===(int)$p['id']?'Reviewing now →':'Open review ↗' ?></small></a><?php endforeach;if(!$list['rows'])emptyState('No assigned projects','An Admin must assign a project before you can access it.'); ?></div><div class="pagination"><span>Page <?= $list['page'] ?></span><?php if($list['page']>1): ?><a href="?page=<?= $list['page']-1 ?>&amp;status=<?= esc($status) ?>">Previous</a><?php endif; ?><?php if($list['total']>$list['page']*20): ?><a href="?page=<?= $list['page']+1 ?>&amp;status=<?= esc($status) ?>">Next</a><?php endif; ?></div></section><section class="panel" id="review-guide"><h2>Review checklist</h2><ol class="checklist"><li>Confirm the drawing and scale</li><li>Locate the observation on the plan</li><li>Recommend a specific next action</li><li>Flag what needs professional validation</li></ol><hr><p class="hint">Need another reviewer or more project access? Contact the assigning Admin<?= $project&&$project['assigner_name']?': '.esc($project['assigner_name']):'.' ?></p></section></aside><div class="stack"><?php if($project): planPreview($project);feedbackComposer($project,$user,$feedback);feedbackHistory($feedback);else: ?><section class="panel"><?php emptyState('Your review workspace is ready','Assigned projects, uploaded plans, private drafts and published feedback will appear here.'); ?></section><?php endif; ?><p class="hint">Your feedback is attributed to you as a human reviewer. It does not replace site-specific professional assessment or certification.</p></div></div>
<?php portalFooter(); ?>
